alter table public.websites alter column country_code drop not null;
alter table public.websites alter column country_code type text;
with measured as ( select w.id, ( select upper(entry->>'country') from jsonb_array_elements(w.audience_split) as entry where entry->>'country' is not null and length(entry->>'country') = 2 order by coalesce((entry->>'share')::numeric, 0) desc limit 1 ) as top_country from public.websites w where w.country_code = 'GB' and w.audience_split is not null and jsonb_typeof(w.audience_split) = 'array' and jsonb_array_length(w.audience_split) > 0 ) update public.websites w set country_code = measured.top_country from measured where w.id = measured.id and measured.top_country is not null and measured.top_country <> 'GB';
with cctld (suffix, country) as (values ('ae', 'AE'), ('al', 'AL'), ('ar', 'AR'), ('at', 'AT'), ('au', 'AU'), ('ba', 'BA'), ('bd', 'BD'), ('be', 'BE'), ('bg', 'BG'), ('bh', 'BH'), ('bo', 'BO'), ('br', 'BR'), ('ca', 'CA'), ('ch', 'CH'), ('ci', 'CI'), ('cl', 'CL'), ('cn', 'CN'), ('cr', 'CR'), ('cu', 'CU'), ('cy', 'CY'), ('cz', 'CZ'), ('de', 'DE'), ('dk', 'DK'), ('dz', 'DZ'), ('ec', 'EC'), ('ee', 'EE'), ('eg', 'EG'), ('es', 'ES'), ('et', 'ET'), ('fi', 'FI'), ('fr', 'FR'), ('gh', 'GH'), ('gr', 'GR'), ('gt', 'GT'), ('hk', 'HK'), ('hn', 'HN'), ('hr', 'HR'), ('hu', 'HU'), ('id', 'ID'), ('ie', 'IE'), ('il', 'IL'), ('in', 'IN'), ('is', 'IS'), ('it', 'IT'), ('jo', 'JO'), ('jp', 'JP'), ('ke', 'KE'), ('kh', 'KH'), ('kr', 'KR'), ('kw', 'KW'), ('kz', 'KZ'), ('lb', 'LB'), ('lk', 'LK'), ('lt', 'LT'), ('lu', 'LU'), ('lv', 'LV'), ('ma', 'MA'), ('mk', 'MK'), ('mn', 'MN'), ('mt', 'MT'), ('mx', 'MX'), ('my', 'MY'), ('ng', 'NG'), ('ni', 'NI'), ('nl', 'NL'), ('no', 'NO'), ('np', 'NP'), ('nz', 'NZ'), ('om', 'OM'), ('pa', 'PA'), ('pe', 'PE'), ('ph', 'PH'), ('pk', 'PK'), ('pl', 'PL'), ('pt', 'PT'), ('py', 'PY'), ('qa', 'QA'), ('ro', 'RO'), ('rs', 'RS'), ('ru', 'RU'), ('sa', 'SA'), ('se', 'SE'), ('sg', 'SG'), ('si', 'SI'), ('sk', 'SK'), ('sn', 'SN'), ('sv', 'SV'), ('th', 'TH'), ('tn', 'TN'), ('tr', 'TR'), ('tw', 'TW'), ('tz', 'TZ'), ('ua', 'UA'), ('ug', 'UG'), ('uk', 'GB'), ('us', 'US'), ('uy', 'UY'), ('uz', 'UZ'), ('ve', 'VE'), ('vn', 'VN'), ('za', 'ZA') ) update public.websites w set country_code = cctld.country from cctld where w.country_code = 'GB' and lower(regexp_replace(w.domain, '^.*\.', '')) = cctld.suffix and cctld.country <> 'GB';
select coalesce(country_code, '(not stated)') as market, count(*) as listings from public.websites group by 1 order by listings desc, market;
